function rareFirst(nums: number[]): number[] {
  const cnt = new Map<number, number>();
  for (const x of nums) cnt.set(x, (cnt.get(x) ?? 0) + 1);
  const buckets: number[][] = Array.from({ length: nums.length + 1 }, () => []);
  for (const [v, c] of cnt) buckets[c].push(v);
  const out: number[] = [];
  for (let c = 1; c <= nums.length; c++) {
    buckets[c].sort((a, b) => b - a);
    for (const v of buckets[c]) for (let k = 0; k < c; k++) out.push(v);
  }
  return out;
}

