class Solution:
    def rareFirst(self, nums: List[int]) -> List[int]:
        cnt = Counter(nums)
        buckets = [[] for _ in range(len(nums) + 1)]
        for v, c in cnt.items():
            buckets[c].append(v)
        out = []
        for c in range(1, len(nums) + 1):
            for v in sorted(buckets[c], reverse=True):
                out.extend([v] * c)
        return out

